import{_ as s,c as a,o as n,a4 as e}from"./chunks/framework.BX6rvgvq.js";const b=JSON.parse('{"title":"FFprobe使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"modules/更多/ffmpeg/learn-ffmpeg/src/C_FFprobe使用指南.md","filePath":"modules/更多/ffmpeg/learn-ffmpeg/src/C_FFprobe使用指南.md","lastUpdated":1773858860000}'),p={name:"modules/更多/ffmpeg/learn-ffmpeg/src/C_FFprobe使用指南.md"},i=e(`<h1 id="ffprobe使用指南" tabindex="-1">FFprobe使用指南 <a class="header-anchor" href="#ffprobe使用指南" aria-label="Permalink to &quot;FFprobe使用指南&quot;">​</a></h1><h4 id="ffprobe-是什么" tabindex="-1">FFprobe 是什么 ？ <a class="header-anchor" href="#ffprobe-是什么" aria-label="Permalink to &quot;FFprobe 是什么 ？&quot;">​</a></h4><p>​ ffprobe 是一个多媒体流分析工具。它从多媒体流中收集信息，并且以人类和机器可读的形式打印出来。它可以用来检测多媒体流的容器类型，以及每一个多媒体流的格式和类型。它可以作为一个独立的应用来使用，也可以结合文本过滤器执行更复杂的处理。</p><h4 id="ffprobe-使用示例" tabindex="-1">FFprobe 使用示例 <a class="header-anchor" href="#ffprobe-使用示例" aria-label="Permalink to &quot;FFprobe 使用示例&quot;">​</a></h4><ul><li><p>最简单的使用方式</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffprobe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.mp4</span></span></code></pre></div></li><li><p>不显示欢迎信息</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffprobe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hide_banner</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.mp4</span></span></code></pre></div></li><li><p>以 JSON 格式显示每个流的信息</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffprobe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hide_banner</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -print_format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -show_streams</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.mp4</span></span></code></pre></div></li><li><p>显示容器格式相关信息</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ffprobe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hide_banner</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -show_format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.mp4</span></span></code></pre></div></li></ul><h4 id="主要选项" tabindex="-1">主要选项 <a class="header-anchor" href="#主要选项" aria-label="Permalink to &quot;主要选项&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>‘-f format’    强制使用的格式  </span></span>
<span class="line"><span>‘-unit’        显示值的单位  </span></span>
<span class="line"><span>‘-prefix’      显示的值使用标准国际单位制词头  </span></span>
<span class="line"><span>‘-byte_binary_prefix’ 对字节值强制使用二进制前缀  </span></span>
<span class="line"><span>‘-sexagesimal’ 时间值使用六十进位的格式 HH:MM:SS.MICROSECONDS  </span></span>
<span class="line"><span>‘-pretty’      美化显示值的格式。它相当于 &quot;-unit -prefix -byte_binary_prefix -sexagesimal&quot;  </span></span>
<span class="line"><span>‘-of, -print_format writer_name[=writer_options]’   </span></span>
<span class="line"><span>              设置输出打印格式。writer_name 指定打印程序 (writer) 的名称，writer_options   </span></span>
<span class="line"><span>              指定传递给 writer 的选项。例如：将输出打印为 JSON 格式：-print_format json   </span></span>
<span class="line"><span>‘-select_streams stream_specifier’   </span></span>
<span class="line"><span>              只选择 stream_specifier 指定的流。该选项只影响那些与流相关的选项  </span></span>
<span class="line"><span>              (例如：show_streams, show_packets, 等)。  </span></span>
<span class="line"><span>              举例：只显示音频流，使用命令：  </span></span>
<span class="line"><span>                ffprobe -show_streams -select_streams a INPUT  </span></span>
<span class="line"><span>‘-show_data’ 显示有效载荷数据，以十六进制和ASCII转储。与 ‘-show_packets’ 结合使用，它将   </span></span>
<span class="line"><span>              dump 包数据；与 ‘-show_streams’ 结合使用，它将 dump codec 附加数据。  </span></span>
<span class="line"><span>‘-show_error’    显示探测输入文件时的错误信息  </span></span>
<span class="line"><span>‘-show_format’   显示输入多媒体流的容器格式信息  </span></span>
<span class="line"><span>‘-show_packets’  显示输入多媒体流中每一个包的信息  </span></span>
<span class="line"><span>‘-show_frames’   显示输入多媒体流中的每一帧以及字幕的信息  </span></span>
<span class="line"><span>‘-show_streams’  显示输入多媒体流中每一个流的信息  </span></span>
<span class="line"><span>‘-show_programs’ 显示输入多媒体流中程序以及它们的流的信息  </span></span>
<span class="line"><span>‘-show_chapters’ 显示格式中存储的章节信息  </span></span>
<span class="line"><span>‘-count_frames’  计算每一个流中的帧数，在相应的段中进行显示  </span></span>
<span class="line"><span>‘-count_packets’ 计算每一个流中的包数，在相应的段中进行显示  </span></span>
<span class="line"><span>‘-show_program_version’   显示程序版本及配置相关信息  </span></span>
<span class="line"><span>‘-show_library_versions’  显示库版本相关信息  </span></span>
<span class="line"><span>‘-show_versions’          显示程序和库版本相关信息。相当于同时设置‘-show_program_version’ 和   </span></span>
<span class="line"><span>                          ‘-show_library_versions’  </span></span>
<span class="line"><span>‘-i input_file’           指定输入文件</span></span></code></pre></div><h4 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h4><ul><li><a href="http://blog.csdn.net/stone_wzf/article/details/45378759#" target="_blank" rel="noreferrer">FFprobe使用指南</a></li></ul>`,9),l=[i];function t(r,o,h,c,d,_){return n(),a("div",null,l)}const f=s(p,[["render",t]]);export{b as __pageData,f as default};
